import{_ as a,o as s,c as t,ag as o}from"./chunks/framework.D2veAa-g.js";const m=JSON.parse('{"title":"嵌入式系统概述","description":"","frontmatter":{"title":"嵌入式系统概述"},"headers":[],"relativePath":"架构师 在线刷题/51CT0题库 章节练习/嵌入式系统架构设计理论与实践（第二版）/嵌入式系统概述.md","filePath":"架构师 在线刷题/51CT0题库 章节练习/嵌入式系统架构设计理论与实践（第二版）/嵌入式系统概述.md","lastUpdated":null}'),i={name:"架构师 在线刷题/51CT0题库 章节练习/嵌入式系统架构设计理论与实践（第二版）/嵌入式系统概述.md"};function r(n,l,c,e,u,d){return s(),t("div",null,[...l[0]||(l[0]=[o('<h1 id="嵌入式系统概述" tabindex="-1">嵌入式系统概述 <a class="header-anchor" href="#嵌入式系统概述" aria-label="Permalink to &quot;嵌入式系统概述&quot;">​</a></h1><blockquote><p>共 14 题 · 题型：单选题 · 来源：51CTO题库</p></blockquote><h2 id="q1-微控制器-mcu-与微处理器-mpu-的本质区别是-1-嵌入式系统低功耗设计主要技术不包括-2-。" tabindex="-1">Q1. 微控制器（MCU）与微处理器（MPU）的本质区别是 （1） ；嵌入式系统低功耗设计主要技术不包括 （2） 。 <a class="header-anchor" href="#q1-微控制器-mcu-与微处理器-mpu-的本质区别是-1-嵌入式系统低功耗设计主要技术不包括-2-。" aria-label="Permalink to &quot;Q1. 微控制器（MCU）与微处理器（MPU）的本质区别是 （1） ；嵌入式系统低功耗设计主要技术不包括 （2） 。&quot;">​</a></h2><ul><li><strong>A.</strong> 集成外设数量</li><li><strong>B.</strong> 主频高低</li><li><strong>C.</strong> 是否内置存储器</li><li><strong>D.</strong> 指令集架构</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q2-微控制器-mcu-与微处理器-mpu-的本质区别是-1-嵌入式系统低功耗设计主要技术不包括-2-。" tabindex="-1">Q2. 微控制器（MCU）与微处理器（MPU）的本质区别是 （1） ；嵌入式系统低功耗设计主要技术不包括 （2） 。 <a class="header-anchor" href="#q2-微控制器-mcu-与微处理器-mpu-的本质区别是-1-嵌入式系统低功耗设计主要技术不包括-2-。" aria-label="Permalink to &quot;Q2. 微控制器（MCU）与微处理器（MPU）的本质区别是 （1） ；嵌入式系统低功耗设计主要技术不包括 （2） 。&quot;">​</a></h2><ul><li><strong>A.</strong> 编译优化</li><li><strong>B.</strong> 算法优化</li><li><strong>C.</strong> 增加核数</li><li><strong>D.</strong> 软硬件协同</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q3-在传统嵌入式系统的硬件组成中-1-不是其主要组成部分-片上系统-soc-的特点是-2-。" tabindex="-1">Q3. 在传统嵌入式系统的硬件组成中 （1） 不是其主要组成部分；片上系统（SoC）的特点是 （2） 。 <a class="header-anchor" href="#q3-在传统嵌入式系统的硬件组成中-1-不是其主要组成部分-片上系统-soc-的特点是-2-。" aria-label="Permalink to &quot;Q3. 在传统嵌入式系统的硬件组成中 （1） 不是其主要组成部分；片上系统（SoC）的特点是 （2） 。&quot;">​</a></h2><ul><li><strong>A.</strong> 微处理器</li><li><strong>B.</strong> 显示器</li><li><strong>C.</strong> 存储器</li><li><strong>D.</strong> 总线</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q4-在传统嵌入式系统的硬件组成中-1-不是其主要组成部分-片上系统-soc-的特点是-2-。" tabindex="-1">Q4. 在传统嵌入式系统的硬件组成中 （1） 不是其主要组成部分；片上系统（SoC）的特点是 （2） 。 <a class="header-anchor" href="#q4-在传统嵌入式系统的硬件组成中-1-不是其主要组成部分-片上系统-soc-的特点是-2-。" aria-label="Permalink to &quot;Q4. 在传统嵌入式系统的硬件组成中 （1） 不是其主要组成部分；片上系统（SoC）的特点是 （2） 。&quot;">​</a></h2><ul><li><strong>A.</strong> 采用了哈佛结构，编译效率高</li><li><strong>B.</strong> 专注于浮点运算，弥补了CPU运算速度不足</li><li><strong>C.</strong> 采用了片内再编程技术，可通过编程配置硬件功能</li><li><strong>D.</strong> 体积小，重量轻，成本低，但技术保密性差</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q5-物联网操作系统的主要特征不包括-。" tabindex="-1">Q5. 物联网操作系统的主要特征不包括（）。 <a class="header-anchor" href="#q5-物联网操作系统的主要特征不包括-。" aria-label="Permalink to &quot;Q5. 物联网操作系统的主要特征不包括（）。&quot;">​</a></h2><ul><li><strong>A.</strong> 内核实时性</li><li><strong>B.</strong> 架构可扩展性</li><li><strong>C.</strong> 高吞吐量处理</li><li><strong>D.</strong> 低功耗</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q6-关于嵌入式数据库的分类-以下说法正确的是-。" tabindex="-1">Q6. 关于嵌入式数据库的分类，以下说法正确的是（ ）。 <a class="header-anchor" href="#q6-关于嵌入式数据库的分类-以下说法正确的是-。" aria-label="Permalink to &quot;Q6. 关于嵌入式数据库的分类，以下说法正确的是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 按嵌入对象分类时，只包括软件嵌入数据库和设备嵌入数据库</li><li><strong>B.</strong> 按系统结构分类时，包括嵌入数据库、移动数据库和大型C/S结构数据库</li><li><strong>C.</strong> 按存储位置分类时，基于内存的数据库系统属于实时事务最佳技术</li><li><strong>D.</strong> 按存储位置分类时，基于文件的数据库具有最高的安全性</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q7-关于嵌入式中间件的描述-以下哪项是正确的-。" tabindex="-1">Q7. 关于嵌入式中间件的描述，以下哪项是正确的（ ）。 <a class="header-anchor" href="#q7-关于嵌入式中间件的描述-以下哪项是正确的-。" aria-label="Permalink to &quot;Q7. 关于嵌入式中间件的描述，以下哪项是正确的（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 嵌入式中间件位于嵌入式应用和硬件之间</li><li><strong>B.</strong> 嵌入式中间件的主要作用是提高系统的实时性能</li><li><strong>C.</strong> 嵌入式中间件对嵌入式应用屏蔽底层操作系统的异构性</li><li><strong>D.</strong> 消息中间件和分布式对象中间件不属于嵌入式中间件</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q8-以下哪种处理器专注于浮点运算-弥补了cpu运算速度不足-。" tabindex="-1">Q8. 以下哪种处理器专注于浮点运算，弥补了CPU运算速度不足（ ）。 <a class="header-anchor" href="#q8-以下哪种处理器专注于浮点运算-弥补了cpu运算速度不足-。" aria-label="Permalink to &quot;Q8. 以下哪种处理器专注于浮点运算，弥补了CPU运算速度不足（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 微处理器（MPU）</li><li><strong>B.</strong> 微控制器（MCU）</li><li><strong>C.</strong> 信号处理器（DSP）</li><li><strong>D.</strong> 图形处理器（GPU）</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><h2 id="q9-在嵌入式系统中-按照计算机所传输的信息种类-以下哪种总线用于传输ram中存储数据的地址-。" tabindex="-1">Q9. 在嵌入式系统中，按照计算机所传输的信息种类，以下哪种总线用于传输RAM中存储数据的地址（ ）。 <a class="header-anchor" href="#q9-在嵌入式系统中-按照计算机所传输的信息种类-以下哪种总线用于传输ram中存储数据的地址-。" aria-label="Permalink to &quot;Q9. 在嵌入式系统中，按照计算机所传输的信息种类，以下哪种总线用于传输RAM中存储数据的地址（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 数据总线</li><li><strong>B.</strong> 地址总线</li><li><strong>C.</strong> 控制总线</li><li><strong>D.</strong> 片内总线</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q10-关于存储器的特性-下列说法正确的是-。" tabindex="-1">Q10. 关于存储器的特性，下列说法正确的是（ ）。 <a class="header-anchor" href="#q10-关于存储器的特性-下列说法正确的是-。" aria-label="Permalink to &quot;Q10. 关于存储器的特性，下列说法正确的是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> RAM断电后数据保持不变</li><li><strong>B.</strong> ROM数据可以随时修改</li><li><strong>C.</strong> RAM断电后数据会清空</li><li><strong>D.</strong> ROM和RAM都可以随时修改数据</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q11-在嵌入式系统中-看门狗-watchdog-的主要功能是什么-。" tabindex="-1">Q11. 在嵌入式系统中，看门狗（Watchdog）的主要功能是什么（ ）。 <a class="header-anchor" href="#q11-在嵌入式系统中-看门狗-watchdog-的主要功能是什么-。" aria-label="Permalink to &quot;Q11. 在嵌入式系统中，看门狗（Watchdog）的主要功能是什么（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 提高系统运行速度</li><li><strong>B.</strong> 监控系统运行状态并在异常时重启系统</li><li><strong>C.</strong> 管理系统内存分配</li><li><strong>D.</strong> 优化系统电源消耗</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q12-在嵌入式系统硬件中-哪个组件的主要功能是在系统发生软件问题或程序异常时重新启动系统-。" tabindex="-1">Q12. 在嵌入式系统硬件中，哪个组件的主要功能是在系统发生软件问题或程序异常时重新启动系统（ ）。 <a class="header-anchor" href="#q12-在嵌入式系统硬件中-哪个组件的主要功能是在系统发生软件问题或程序异常时重新启动系统-。" aria-label="Permalink to &quot;Q12. 在嵌入式系统硬件中，哪个组件的主要功能是在系统发生软件问题或程序异常时重新启动系统（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 微处理器</li><li><strong>B.</strong> 存储器</li><li><strong>C.</strong> 总线</li><li><strong>D.</strong> 看门狗</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><h2 id="q13-嵌入式系统发展历程中-以简单操作系统为核心、具有智能化控制能力突出特点的阶段是-。" tabindex="-1">Q13. 嵌入式系统发展历程中，以简单操作系统为核心、具有智能化控制能力突出特点的阶段是（ ）。 <a class="header-anchor" href="#q13-嵌入式系统发展历程中-以简单操作系统为核心、具有智能化控制能力突出特点的阶段是-。" aria-label="Permalink to &quot;Q13. 嵌入式系统发展历程中，以简单操作系统为核心、具有智能化控制能力突出特点的阶段是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> SCM单片微型计算机</li><li><strong>B.</strong> MCU微控制器</li><li><strong>C.</strong> SoC片上系统</li><li><strong>D.</strong> 以Internet为基础的嵌入式系统</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q14-【问题1】-5分-王工拟采用的-ros-具有分布式进程框架-以点对点设计以及服务和节点管理器方式-使得执行程序可以各自独立地设计-松散地、实时地组合起来。这些进程可以按照功能包和功能包集的方式分组-因而可以容易地分享和发布。请用-400-字以内文字说明-ros-与嵌入式实时操作系统的共同点-以及在实时性和任务通信方式两个方面的差异。" tabindex="-1">Q14. 【问题1】（5分）王工拟采用的 ROS 具有分布式进程框架，以点对点设计以及服务和节点管理器方式， 使得执行程序可以各自独立地设计，松散地、实时地组合起来。这些进程可以按照功能包和功能包集的方式分组，因而可以容易地分享和发布。请用 400 字以内文字说明 ROS 与嵌入式实时操作系统的共同点，以及在实时性和任务通信方式两个方面的差异。 <a class="header-anchor" href="#q14-【问题1】-5分-王工拟采用的-ros-具有分布式进程框架-以点对点设计以及服务和节点管理器方式-使得执行程序可以各自独立地设计-松散地、实时地组合起来。这些进程可以按照功能包和功能包集的方式分组-因而可以容易地分享和发布。请用-400-字以内文字说明-ros-与嵌入式实时操作系统的共同点-以及在实时性和任务通信方式两个方面的差异。" aria-label="Permalink to &quot;Q14. 【问题1】（5分）王工拟采用的 ROS 具有分布式进程框架，以点对点设计以及服务和节点管理器方式， 使得执行程序可以各自独立地设计，松散地、实时地组合起来。这些进程可以按照功能包和功能包集的方式分组，因而可以容易地分享和发布。请用 400 字以内文字说明 ROS 与嵌入式实时操作系统的共同点，以及在实时性和任务通信方式两个方面的差异。&quot;">​</a></h2><details class="callout callout-info"><summary class="callout-title"><span class="callout-icon">ℹ️</span>材料</summary><div class="callout-body"><p>试题三（25分）阅读以下关于机器人操作系统架构的描述，回答问题 1 至问题 3【说明】随着人工智能技术的发展，工业机器人已成为当前工业界的热点研究对象。某宇航设备公司为了扩大业务范围，决策层研究决定准备开展工业机器人研制新业务。公司将论证工作交给了软件架构师王工，王工经过分析和调研，从机器人市场现状、领域需求、 组成及关键技术和风险分析等方面开展了综合论证。论证报告指出:首先，为了保障本公司机器人研制的持续性，应根据领域需求选择一种适应的设计架构:其次，为了规避风险，公司的研制工作不能从零开始，应该采用国际开源社区所提供机器人操作系统 (Robot Operating System ，ROS)作为机器人开发的基本平台。在讨论会上，架构师李工提出不同意见，他认为公司针对宇航领域已开发了某款嵌入式实时操作系统，且被多种宇航装备使用，可靠性较高。因此应该采用现有架构体系作为机器人的开发平台。会上王工说明了机器人操作系统与该款操作系统的差别，要沿用需要进行改造，技入较大。经过激烈讨论，公司领导同意了王工采用 ROS 的意见。</p></div></details><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>共同点如下：（1）系统专用型强（2）系统资源有限（3）系统都采用嵌入式微型处理器（4）软硬件依赖性强差异：实时性：ROS弱于嵌入式实时操作系统通信方式：ROS通信方式丰富，嵌入式实时操作系统通信方式单一。</p></div></details>',44)])])}const h=a(i,[["render",r]]);export{m as __pageData,h as default};
